};

pub const StoredAddr = extern struct {
    bytes: [SOCKADDR_IN6_LEN]u8 = undefined,
    len: u8 = 0,

pub fn zero() StoredAddr {
            return StoredAddr{ .bytes = @splat(0), .len = 0 };
    }

pub fn fromRaw(ptr: ?[*]const u8, raw_len: usize) StoredAddr {
            var out = StoredAddr.zero();
            _ = &out;
            if (ptr) |p| {
                _ = &p;
                const n = @min(raw_len, SOCKADDR_IN6_LEN);
                _ = @memcpy(out.bytes[0..n], (blk: {
                break :blk p[0..n];

}));
                out.len = @intCast(n);
            }
            return out;
    }

pub fn asSockaddrPtr(self: *const StoredAddr) ?*const posix.sockaddr {
            if ((self.len == 0)) {
                return null;
            }
            return (blk: {
            break :blk @as(*const posix.sockaddr, @ptrCast(@alignCast(&(self.bytes))));

});
    }

pub fn family(self: StoredAddr) u16 {
            if ((self.len < 2)) {
                return 0;
            }
            if (comptime bun.Environment.isMac) {
                return (if (comptime @typeInfo(@TypeOf(self.bytes[1])) == .@"enum") cp_cast_int(u16, @intFromEnum(self.bytes[1])) else cp_cast_int(u16, self.bytes[1]));
            }
            return std.mem.readInt(u16, self.bytes[0..2], .little);
    }

pub fn port(self: StoredAddr) u16 {
            if ((self.len < 4)) {
                return 0;
            }
            return std.mem.readInt(u16, self.bytes[2..4], .big);
    }

pub fn toJSSocketAddress(self: StoredAddr, global: *JSGlobalObject) JSValue {
            const fam = self.family();
            const p = self.port();
            if (((fam == posix.AF.INET) and (self.len >= SOCKADDR_IN_LEN))) {
                const addr = SocketAddress.initIPv4((self.bytes[4..8]).*, p);
                return SocketAddress.@"new"(addr).toJS(global);
            }
            if (((fam == posix.AF.INET6) and (self.len >= SOCKADDR_IN6_LEN))) {
                const addr = SocketAddress.initIPv6((self.bytes[8..24]).*, p, 0, 0);
                return SocketAddress.@"new"(addr).toJS(global);
            }
            return JSValue.js_undefined;
    }
};

pub const SessionState = extern struct {
