pub const HskSnapshot = struct {
    sni: ?[]u8 = null,
    cipher: ?[]u8 = null,
    alpn: ?[]u8 = null,
    validation: ?tls.ValidationErrorStrings = null,
    peer_cert_der: ?[]u8 = null,
    local_cert_der: ?[]u8 = null,
    ephemeral: ?tls.EphemeralKeyInfo = null,
    early_data_attempted: bool = false,
    early_data_accepted: bool = false,
    __cp_dropped: bool = false,

pub fn __cp_deinit(self: *HskSnapshot) void {
        if (self.__cp_dropped) return;
        self.__cp_dropped = true;
            const alloc = bun.default_allocator;
            if (self.sni) |v| {
                _ = &v;
                _ = alloc.free(v);
            }
            if (self.cipher) |v| {
                _ = &v;
                _ = alloc.free(v);
            }
            if (self.alpn) |v| {
                _ = &v;
                _ = alloc.free(v);
            }
            if (self.peer_cert_der) |v| {
                _ = &v;
                _ = alloc.free(v);
            }
            if (self.local_cert_der) |v| {
                _ = &v;
                _ = alloc.free(v);
            }
    }
};

pub const DeferredAbort = struct {
