    marker: u64,
};

pub const CloseSpec = struct {
    app: bool = false,
    code: u64 = 0,
    reason: []u8 = "",
    __cp_dropped: bool = false,

pub fn __cp_deinit(self: *CloseSpec) void {
        if (self.__cp_dropped) return;
        self.__cp_dropped = true;
            if ((self.reason.len > 0)) {
                _ = bun.default_allocator.free(self.reason);
                self.reason = "";
            }
    }
};

