};

pub const SessionInner = struct {
    endpoint_js: jsc.Strong.Optional = .empty,
    events: std.ArrayListUnmanaged(SessionEvent) = .{},
    origin_buf: std.ArrayListUnmanaged(u8) = .{},
    deferred_aborts: std.ArrayListUnmanaged(DeferredAbort) = .{},
    pending_graceful: ?CloseSpec = null,
    peer_close: ?CloseSpec = null,
    self_close: ?CloseSpec = null,
    deferred_close: ?CloseSpec = null,
    datagram_queue: std.ArrayListUnmanaged(DatagramItem) = .{},
    inflight_datagrams: std.ArrayListUnmanaged(u64) = .{},
    pending_tickets: std.ArrayListUnmanaged(TicketItem) = .{},
    final_conn_status: c_int = 0,
    final_conn_msg: ?[]u8 = null,
    has_final_conn_status: bool = false,
    pending_local_bidi: std.ArrayListUnmanaged(?*stream.QuicStream) = .{},
    pending_local_uni: std.ArrayListUnmanaged(?*stream.QuicStream) = .{},
    streams: std.ArrayListUnmanaged(*stream.QuicStream) = .{},
    hsk_snapshot: ?HskSnapshot = null,
    application_options_js: jsc.Strong.Optional = .empty,
    this_value: jsc.JSRef = .empty(),
    __cp_dropped: bool = false,

pub fn __cp_deinit(self: *SessionInner) void {
        if (self.__cp_dropped) return;
        self.__cp_dropped = true;
            const alloc = bun.default_allocator;
            _ = self.endpoint_js.deinit();
            _ = self.application_options_js.deinit();
            for (self.events.items) |ev| {
                _ = &ev;
                _ = freeEventBytes(ev);
            }
            _ = self.events.deinit(alloc);
            _ = self.origin_buf.deinit(alloc);
            _ = self.deferred_aborts.deinit(alloc);
            if (self.pending_graceful) |pg| {
                _ = &pg;
                _ = pg.__cp_deinit();
            }
            if (self.peer_close) |pc| {
                _ = &pc;
                _ = pc.__cp_deinit();
            }
            if (self.self_close) |sc| {
                _ = &sc;
                _ = sc.__cp_deinit();
            }
            if (self.deferred_close) |dc| {
                _ = &dc;
                _ = dc.__cp_deinit();
            }
            for (self.datagram_queue.items) |d| {
                _ = &d;
                _ = alloc.free(d.payload);
            }
            _ = self.datagram_queue.deinit(alloc);
            _ = self.inflight_datagrams.deinit(alloc);
            for (self.pending_tickets.items) |t| {
                _ = &t;
                _ = alloc.free(t.blob);
            }
            _ = self.pending_tickets.deinit(alloc);
            if (self.final_conn_msg) |m| {
                _ = &m;
                _ = alloc.free(m);
            }
            _ = self.pending_local_bidi.deinit(alloc);
            _ = self.pending_local_uni.deinit(alloc);
            _ = self.streams.deinit(alloc);
            if (self.hsk_snapshot) |hs| {
                _ = &hs;
                _ = hs.__cp_deinit();
            }
    }
};

pub const QuicSession = extern struct {
