    global: *JSGlobalObject,
    inner: *SessionInner,

pub fn create(global: *JSGlobalObject, vtable: *const ffi.NqVtable, ep: *endpoint.QuicEndpoint, endpoint_handle: JSValue, conn: ?*ffi.lsquic_conn, is_server: bool) bun.JSError!*QuicSession {
