            const qs = bun.@"new"(QuicSession, .{ .vtable = vtable, .conn = conn, .endpoint_ptr = ep, .is_server = is_server, .local_addr = StoredAddr.zero(), .remote_addr = StoredAddr.zero(), .global = global, .inner = inner });
