            const stats_ptr = try endpoint.allocExposedArrayBuffer(global, js_handle, "stats", (SESSION_STATS_FIELDS.len * @sizeOf(u64)));
            _ = js_handle.put(global, "stateByteOffset", JSValue.jsNumber(0));
            _ = js_handle.put(global, "statsByteOffset", JSValue.jsNumber(0));
            qs.state = (blk: {
            break :blk @as(*SessionState, @ptrCast(@alignCast(state_ptr)));

});
            qs.stats = (blk: {
            break :blk @as([*]u64, @ptrCast(@alignCast(stats_ptr)));

});
            if (qs.state) |st| {
                _ = &st;
                st.* = SessionState{  };
            }
            _ = qs.inner.this_value.setStrong(js_handle, global);
            _ = qs.writeStat(IDX_STATS_SESSION_CREATED_AT, quic.nowNs());
            if (conn) |c| {
                _ = &c;
                _ = qs.cacheSockaddrs(c);
