            self.conn = conn;
            _ = ffi.lsquic_conn_set_ctx(conn, (blk: {
            break :blk @as(?*anyopaque, self);

}));
            if (self.endpoint_ptr) |ep| {
                _ = &ep;
                const ssl_ptr = ffi.lsquic_conn_get_ssl(conn);
                _ = ep.takeAndPushEarlyKeylog(ssl_ptr, self);
