            _ = self.cacheSockaddrs(conn);
            if (self.close_when_bound) {
                if (self.inner.pending_graceful) |*pg| {
                    _ = &pg;
                    const reason = (pg.*).reason;
                    (pg.*).reason = "";
                    const app = (pg.*).app;
                    const code = (pg.*).code;
                    self.inner.pending_graceful = null;
                    _ = self.applyGracefulClose(app, code, reason);
                }
            }
    }

pub fn cacheSockaddrs(self: *QuicSession, conn: *ffi.lsquic_conn) void {
