                break :blk @as([*]const u8, @alignCast(@ptrCast(peer)));

}), SOCKADDR_IN6_LEN);
            }
    }

pub fn hasListener(self: QuicSession, flag: u32) bool {
            if (self.state) |st| {
                _ = &st;
                return ((st.listener_flags & flag) != 0);
            }
            return false;
    }

pub fn addStat(self: *QuicSession, idx: usize, delta: u64) void {
            if (self.stats) |*stats| {
                _ = &stats;
                if ((idx < SESSION_STATS_FIELDS.len)) {
                    {
